-- The stage_history trigger stamps changed_at = insert time (now()), which
-- would collapse every seeded deal onto the day this script was run. Backdate
-- each entity's single history row to the fabricated created_at so daily/
-- weekly trend views show a realistic spread. NOTE: because seed opportunities
-- are inserted directly at their terminal demo stage (not simulated through
-- every intermediate transition), this backdating is a simplification for
-- demo purposes only — see docs/known-limitations.md.
update stage_history sh set changed_at = o.created_at from opportunities o where sh.entity_type = 'opportunity' and sh.entity_id = o.id;
update stage_history sh set changed_at = l.created_at from leads l where sh.entity_type = 'lead' and sh.entity_id = l.id;

-- Refresh alerts based on the seeded data above.
select generate_alerts();
